import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 8
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = iter(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))
    fallback = None
    pending = []

    for record in records:
        if len(record) == expected_width and any(value.strip() for value in record):
            columns = record
            pending = []
            break
        if fallback is not None:
            pending.append(record)
        elif any(value.strip() for value in record):
            fallback = record
    else:
        if fallback is None:
            return {"columns": [], "rows": []}
        columns = fallback

    amount_pattern = re.compile(r"[+-]?[0-9]{1,3}(?:,[0-9]{3})+(?:\.[0-9]+)?")
    rows = pending + list(records)
    width = max(expected_width, len(columns))

    for row in rows:
        if len(row) > expected_width:
            tail = row[expected_width - 1:]
            amount = ",".join(tail)
            if all("," not in value for value in tail) and amount_pattern.fullmatch(amount.strip()):
                row[expected_width - 1:] = [amount]
        width = max(width, len(row))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"Column_{position}" if position <= expected_width else f"Extra_{position - expected_width}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
